type Store = {
  insert(table: string): { values(row: object): Promise<void> };
};

type Graph = {
  writeRelationships(facts: readonly object[]): Promise<void>;
};

/** Creates an order and records who owns it. */
export async function createOrder(
  db: Store,
  graph: Graph,
  id: string,
): Promise<void> {
  await db.insert("orders").values({ id });
  await graph.writeRelationships([{ resource: id, relation: "owner" }]);
}
